frame_eqs_eel:
kick = max(bass - bass_att, 0);
pulse = max(pulse * 0.86, min(kick * 0.9, 1));
q3 = pulse;
pop = max(pop * 0.78, min(max(bass - 1.2, 0) * 0.55, 1.4));
q5 = pop;
dt = min(1 / max(fps, 1), 0.1);
loud = min((bass_att + mid_att + treb_att) / 3, 2);
spd_m = spd_m + (0.9 + 0.9 * loud - spd_m) * (1 - exp(-dt / 1.0));
spd = spd + (spd_m - spd) * (1 - exp(-dt / 1.0));
fly = max(spd * (1 + 0.45 * q3), 0.25);
dd = dd + fly * dt;
dd = dd - 64 * floor(dd / 64);
ttw = ttw - dt;
ttw_n = below(ttw, 0);
twg = if(ttw_n, (rand(1000) / 1000 * 2 - 1) * 0.12, twg);
