tw_m = tw_m + (twg - tw_m) * (1 - exp(-dt / 2.5));
tw = tw + (tw_m - tw) * (1 - exp(-dt / 2.5));
psi = psi + tw * fly * dt;
psi = psi - 6.2831853 * floor(psi / 6.2831853);
trw = trw - dt;
trw_n = below(trw, 0);
rwg = if(trw_n, (rand(1000) / 1000 * 2 - 1) * 0.25, rwg);
trw = if(trw_n, 6 + rand(1000) / 1000 * 4, trw);
rw_m = rw_m + (rwg - rw_m) * (1 - exp(-dt / 1.5));
rw = rw + (rw_m - rw) * (1 - exp(-dt / 1.5));
roll = roll + rw * dt;
roll = roll - 6.2831853 * floor(roll / 6.2831853);
tpan = tpan - dt;
tpan_n = below(tpan, 0);
pgx = if(tpan_n, (rand(1000) / 1000 * 2 - 1) * 0.06, pgx);
pgy = if(tpan_n, (rand(1000) / 1000 * 2 - 1) * 0.05, pgy);
tpan = if(tpan_n, 5 + rand(1000) / 1000 * 3, tpan);
px_m = px_m + (pgx - px_m) * (1 - exp(-dt / 1.4));
px = px + (px_m - px) * (1 - exp(-dt / 1.4));
py_m = py_m + (pgy - py_m) * (1 - exp(-dt / 1.4));
py = py + (py_m - py) * (1 - exp(-dt / 1.4));
tfoc = tfoc - dt;
tfoc_n = below(tfoc, 0);
focg = if(tfoc_n, 1.05 + rand(1000) / 1000 * 0.5, focg);
tfoc = if(tfoc_n, 9 + rand(1000) / 1000 * 6, tfoc);
foc_m = foc_m + (focg - foc_m) * (1 - exp(-dt / 3));
foc = foc + (foc_m - foc) * (1 - exp(-dt / 3));
tbend = tbend - dt;
tbend_n = below(tbend, 0);
a1g = if(tbend_n, 0.08 + rand(1000) / 1000 * 0.2, a1g);
a2g = if(tbend_n, rand(1000) / 1000 * 0.04, a2g);
tbend = if(tbend_n, 12 + rand(1000) / 1000 * 6, tbend);
a1_m = a1_m + (a1g - a1_m) * (1 - exp(-dt / 3.5));
a1 = a1 + (a1_m - a1) * (1 - exp(-dt / 3.5));
a2_m = a2_m + (a2g - a2_m) * (1 - exp(-dt / 3.5));
a2 = a2 + (a2_m - a2) * (1 - exp(-dt / 3.5));
q20 = a1; q21 = a2;
gx0 = q20 * cos(0.098174770 * (dd)) + q21 * cos(3 * 0.098174770 * (dd) + 1.3);
gy0 = q20 * sin(0.098174770 * (dd)) + q21 * sin(2 * 0.098174770 * (dd) + 0.4);
tx = -q20 * 0.098174770 * sin(0.098174770 * dd) - q21 * 3 * 0.098174770 * sin(3 * 0.098174770 * dd + 1.3);
ty = q20 * 0.098174770 * cos(0.098174770 * dd) + q21 * 2 * 0.098174770 * cos(2 * 0.098174770 * dd + 0.4);
gxf = q20 * cos(0.098174770 * (dd + 16)) + q21 * cos(3 * 0.098174770 * (dd + 16) + 1.3);
gyf = q20 * sin(0.098174770 * (dd + 16)) + q21 * sin(2 * 0.098174770 * (dd + 16) + 0.4);
q26 = (gxf - gx0 - 16 * tx) / foc;
q27 = (gyf - gy0 - 16 * ty) / foc;
q7 = cos(roll); q8 = sin(roll);
q9 = dd - floor(dd); q10 = floor(dd);
q11 = gx0; q12 = gy0; q13 = tx; q14 = ty;
q15 = px; q16 = py; q17 = foc; q18 = psi; q19 = tw;
breath = breath + dt * 0.21;
breath = breath - 6.2831853 * floor(breath / 6.2831853);
q22 = breath;
hue = hue + dt * 0.005;
hue = hue - floor(hue);
q23 = hue;
q24 = dd / 16;
core = core + (min(bass_att, 2) - core) * (1 - exp(-dt / 0.4));
q25 = core;
q28 = min(0.0012 + 0.0022 * fly, 0.012);
q29 = min(0.66 + 0.1 * q3, 0.8);

warp:
vec2 inf_path(float pu) {
  return vec2(q20 * cos(0.098174770 * pu) + q21 * cos(3.0 * 0.098174770 * pu + 1.3),
              q20 * sin(0.098174770 * pu) + q21 * sin(2.0 * 0.098174770 * pu + 0.4));
}
float inf_hash(float hu) {
  return fract(sin(hu * 12.9898 + 4.1) * 43758.5453);
}
vec3 inf_ramp(float rx) {
  float rr_x = clamp(rx, 0.0, 1.0) * 5.0;
  vec3 rr = mix(NOKKVI_RAMP0, NOKKVI_RAMP1, clamp(rr_x, 0.0, 1.0));
  rr = mix(rr, NOKKVI_RAMP2, clamp(rr_x - 1.0, 0.0, 1.0));
  rr = mix(rr, NOKKVI_RAMP3, clamp(rr_x - 2.0, 0.0, 1.0));
  rr = mix(rr, NOKKVI_RAMP4, clamp(rr_x - 3.0, 0.0, 1.0));
  rr = mix(rr, NOKKVI_RAMP5, clamp(rr_x - 4.0, 0.0, 1.0));
  return rr;
}
float inf_hoop(vec2 hc, float hh) {
  float hr = length(hc);
  float ha = atan(hc.y, hc.x);
  float lobes = 3.0 + floor(hh * 3.0);
  float amp = 0.028 * (0.55 + 0.45 * sin(q22 + hh * 6.2831853));
  float rad0 = 0.30 + 0.05 * (hh - 0.5);
  return abs(hr - rad0 - amp * sin(lobes * ha + hh * 6.2831853)) / (1.0 + lobes * amp / rad0);
}
float inf_frame(vec2 fc, float fh) {
  vec2 fb = vec2(0.30, 0.22 + 0.08 * fh);
  vec2 fq = abs(fc) - fb + 0.06;
  float fd = length(max(fq, 0.0)) + min(max(fq.x, fq.y), 0.0) - 0.06;
  return abs(fd);
}
float inf_fbm(vec2 nc) {
  float fs = 0.0;
  float fa = 0.5;
  vec2 fx = nc;
  for (int o = 0; o < 4; o++) {
    fs += fa * texture(sampler_noise_hq, fx).x;
    fx = fx * 2.0 + vec2(0.37, 0.61);
    fa *= 0.5;
  }
  return fs;
}
float inf_haze(vec2 tc) {
  float hs = 0.0;
  for (int l = 0; l < 3; l++) {
    float lp = q24 + float(l) / 3.0;
    float ph = fract(lp);
    float lid = mod(floor(lp), 4.0) * 3.0 + float(l);
    float lsc = 0.05 * exp2(3.0 * (1.0 - ph));
    float la = lid * 2.39996;
    vec2 lc = vec2(tc.x * cos(la) - tc.y * sin(la), tc.x * sin(la) + tc.y * cos(la)) * lsc
              + vec2(0.31, 0.17) * lid;
    float wn = inf_fbm(lc * 0.6 + vec2(0.5, 0.2));
    vec2 wc = lc + vec2(wn, -wn) * 0.35;
    hs += inf_fbm(wc) * sin(3.14159265 * ph);
  }
  return hs / 1.5;
}
 shader_body {
  vec2 s = texsize.xy / min(texsize.x, texsize.y);
  vec2 sp = (uv_orig - 0.5) * s + vec2(q15, q16);
  vec2 p = vec2(sp.x * q7 + sp.y * q8, -sp.x * q8 + sp.y * q7);
  float pix = 1.0 / min(texsize.x, texsize.y);
  vec3 acc = vec3(0.0);
  float cov = 0.0;
  for (int i = 0; i < 16; i++) {
    float z = (float(i) + 1.0 - q9) / 16.0;
    float w = smoothstep(0.0, 0.12, z) * smoothstep(1.0, 0.72, z);
    float u = q10 + float(i) + 1.0;
    vec2 ctr = inf_path(u) - vec2(q11, q12) - (u - q10 - q9) * vec2(q13, q14);
    vec2 c = p * (q17 * z) - ctr;
    float th = q18 + q19 * 16.0 * z;
    c = vec2(c.x * cos(th) - c.y * sin(th), c.x * sin(th) + c.y * cos(th));
    float h = inf_hash(mod(u, 64.0));
    float pw = q17 * z * pix;
    float d = inf_hoop(c, h) - 0.0035;
    float line = smoothstep(pw, -pw, d);
    float gs = 0.008 + pw;
    float glow = gs * gs / (d * d + gs * gs);
    vec3 pcol = inf_ramp(0.25 + 0.7 * fract(h * 0.73 + q23));
    float fog = 1.0 - exp(-2.2 * z);
    pcol = mix(pcol, vec3(dot(pcol, vec3(0.299, 0.587, 0.114))), 0.45 * z);
    vec3 lcol = mix(pcol * (1.0 + 0.35 * q5 + 0.2 * q3), NOKKVI_BG, fog * 0.8);
    float a = w * line;
    acc += (1.0 - cov) * (a * lcol + w * glow * 0.12 * (1.0 - line) * lcol);
    cov += (1.0 - cov) * a;
  }
  vec2 hp = p - vec2(q26, q27);
  float hr = length(hp) + 0.0001;
  float hz = inf_haze(hp);
  float hzf = smoothstep(0.42, 0.06, hr);
  float fil = pow(1.0 - abs(2.0 * clamp(hz, 0.0, 1.0) - 1.0), 5.0);
  float hzc_x = clamp(0.15 + 0.75 * smoothstep(0.2, 0.8, hz), 0.0, 1.0) * 5.0;
  vec3 hzc = mix(NOKKVI_RAMP0, NOKKVI_RAMP1, clamp(hzc_x, 0.0, 1.0));
  hzc = mix(hzc, NOKKVI_RAMP2, clamp(hzc_x - 1.0, 0.0, 1.0));
  hzc = mix(hzc, NOKKVI_RAMP3, clamp(hzc_x - 2.0, 0.0, 1.0));
  hzc = mix(hzc, NOKKVI_RAMP4, clamp(hzc_x - 3.0, 0.0, 1.0));
  hzc = mix(hzc, NOKKVI_RAMP5, clamp(hzc_x - 4.0, 0.0, 1.0));
  vec3 back = mix(NOKKVI_BG, NOKKVI_SURFACE, 0.35 * hzf * smoothstep(0.2, 0.7, hz));
  back += hzc * fil * hzf * (0.35 + 0.25 * q25);
  float cg = 0.02 / (0.02 + hr * hr * 40.0);
  back += mix(NOKKVI_ACCENT, NOKKVI_TEXT, 0.3) * cg * (0.12 + 0.18 * q25);
  vec3 col = acc + (1.0 - cov) * back;
